import os
import ast

files_with_legacy_auth = []
for root, dirs, files in os.walk("app"):
    for file in files:
        if file.endswith(".py"):
            path = os.path.join(root, file)
            with open(path, "r", encoding="utf-8") as f:
                content = f.read()
                if "legacy_auth" in content:
                    files_with_legacy_auth.append(path)

print(f"Found {len(files_with_legacy_auth)} files with 'legacy_auth'.")

keywords = ["create_", "update_", "delete_", "save_", "write_", "POST", "PUT", "PATCH"]

for path in sorted(files_with_legacy_auth):
    if path == "app/auth.py":
        continue
    with open(path, "r", encoding="utf-8") as f:
        source = f.read()

    tree = ast.parse(source, filename=path)
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef):
            # Check if legacy_auth is called in this function
            calls_legacy_auth = False
            for child in ast.walk(node):
                if isinstance(child, ast.Call) and isinstance(child.func, ast.Name) and child.func.id == "legacy_auth":
                    calls_legacy_auth = True
                    break

            if calls_legacy_auth:
                func_source = ast.get_source_segment(source, node)
                if func_source is None:
                    func_source = ""
                matches = [kw for kw in keywords if kw in func_source]
                # Also check file name/path
                file_matches = [kw for kw in keywords if kw in path]
                print(f"File: {path}, Func: {node.name}")
                print(f"  Keywords in function: {matches}")
                print(f"  Keywords in path: {file_matches}")
                # Print function source
                print("  Source:")
                for line in func_source.splitlines():
                    print(f"    {line}")
                print("-" * 40)

