import os

keywords = ["create_", "update_", "delete_", "save_", "write_", "POST", "PUT", "PATCH"]
keywords_no_underscore = ["create", "update", "delete", "save", "write", "post", "put", "patch"]

for root, dirs, files in os.walk("app"):
    for file in files:
        if file.endswith(".py") and file != "auth.py":
            path = os.path.join(root, file)
            with open(path, "r") as f:
                content = f.read()
            for kw in keywords:
                if kw in content:
                    print(f"Exact match {kw} in {path}")
            for kw in keywords_no_underscore:
                if kw in content.lower():
                    print(f"Case-insensitive match {kw} in {path}")

import os
import ast

for root, dirs, files in os.walk("app"):
    for file in files:
        if file.endswith(".py") and file != "auth.py":
            path = os.path.join(root, file)
            with open(path, "r") as f:
                content = f.read()
            if "legacy_auth" in content:
                tree = ast.parse(content, filename=path)
                for node in ast.walk(tree):
                    if isinstance(node, ast.FunctionDef):
                        calls_legacy_auth = False
                        for child in ast.walk(node):
                            if isinstance(child, ast.Call) and isinstance(child.func, ast.Name) and child.func.id == "legacy_auth":
                                calls_legacy_auth = True
                                break
                        if calls_legacy_auth:
                            has_payload = any(arg.arg == "payload" for arg in node.args.args)
                            func_src = ast.get_source_segment(content, node) or ""
                            print(f"{path}::{node.name} -> has_payload={has_payload}, returns_created={'created' in func_src}, returns_updated={'updated' in func_src}")
